from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject


class SoftwareInventory(SchemaObject):
    active = SchemaField(name="active")
    files = SchemaField(name="files")
    hw_unit = SchemaField(name="hwUnit")
    sw_version = SchemaField(name="swVersion")

    def __init__(self, active, files, hw_unit, sw_version):
        self.active = active
        self.files = files
        self.hw_unit = hw_unit
        self.sw_version = sw_version

        super(SoftwareInventory, self).__init__()


class SoftwareUpdateStatus(SchemaObject):
    next_filename = SchemaField(name="nextFilename", optional=True)
    update_progress = SchemaField(name="updateProgress", not_null=True)

    def __init__(self, update_progress, next_filename=None):
        self.next_filename = next_filename
        self.update_progress = update_progress

        super(SoftwareUpdateStatus, self).__init__()


class RunningSoftwareSlot(SchemaObject):
    status = SchemaField(name="status")
    running = SchemaField(name="running")
    mode = SchemaField(name="mode")
    id = SchemaField(name="id")
    version = SchemaField(name="version")

    def __init__(self, status, running, mode, id, version):
        self.status = status
        self.running = running
        self.mode = mode
        self.id = id
        self.version = version

        super(RunningSoftwareSlot, self).__init__()


class RunningSofware(SchemaObject):
    status = SchemaField(name="status")
    slots = SchemaField(name="slots", many=True, klass=RunningSoftwareSlot)

    def __init__(self, status, slots):
        self.status = status
        self.slots = slots

        super(RunningSofware, self).__init__()


class BtsInfo(SchemaObject):
    software = SchemaField(name="software", klass=RunningSofware)

    def __init__(self, software):
        self.software = software

        super(BtsInfo, self).__init__()
